    28	            $$PWD/telemetry/ValuesFile.hpp \
    29	            $$PWD/telemetry/BinaryFormat.hpp \
    30	            $$PWD/telemetry/detail/BinaryWriter.hpp \
    31	            $$PWD/telemetry/detail/BlockStream.hpp \
    32	            $$PWD/telemetry/detail/BinaryScalar.hpp \
