     1	/**
     2	 * @file TelemetryCatalog.h
     3	 * @brief Borrowed, definition-time validated telemetry field groups.
     4	 * @author Ruslan Kovtun (shpegun60), codexAi
     5	 * License: MIT; see ../LICENSE.
