 57	    std::uint64_t number(unsigned width)
 58	    {
 59	        CHECK(width <= 8 && width <= bytes.size() - offset);
 60	        std::uint64_t result = 0;
 61	        for (unsigned i = 0; i < width; ++i)
 62	        {
 63	            result |= std::uint64_t(std::to_integer<unsigned>(bytes[offset++])) << (i * 8);
 64	        }
 65	        return result;
 66	    }
