 68	    unsigned u8()
 69	    {
 70	        return static_cast<unsigned>(number(1));
 71	    }
 72	
 73	    unsigned u16()
 74	    {
 75	        return static_cast<unsigned>(number(2));
 76	    }
 77	
 78	    std::uint32_t u32()
 79	    {
 80	        return static_cast<std::uint32_t>(number(4));
 81	    }
