135	        state ^= state << 17;
136	        const std::array<Scalar, 4> inputs{
137	            Scalar::fromU64(state), Scalar::fromS64(std::bit_cast<std::int64_t>(state)),
138	            Scalar::fromF32(std::bit_cast<float>(static_cast<std::uint32_t>(state))),
