 45	constexpr FieldType enumType<Earlier>() noexcept
 46	{
 47	    if (!std::is_constant_evaluated())
 48	    {
 49	        ++typeVisits[0];
 50	    }
 51	    return FieldType{ScalarType::U16, &Observed<0>::ops}.withLimits(0, 0, 0);
 52	}
