 54	template <>
 55	constexpr FieldType enumType<Selected>() noexcept
 56	{
 57	    if (!std::is_constant_evaluated())
 58	    {
 59	        ++typeVisits[1];
 60	    }
 61	    return FieldType{ScalarType::U16, &Observed<1>::ops}.withLimits(0, 0, 0);
